 "content": "from math import gcd
from functools import reduce


def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    eight = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8]
    clue = [(r, c) for r in range(h) for c in range(w) if grid[r][c] not in (0, 8)]
    if not eight or not clue:
        return out

    # The 8-pattern consists of square tiles; infer their side from its run lengths.
    runs = []
    for r in range(h):
        c = 0
        while c < w:
            if grid[r][c] == 8:
                start = c
                while c < w and grid[r][c] == 8:
                    c += 1
                runs.append(c - start)
            else:
                c += 1
    for c in range(w):
        r = 0
        while r < h:
            if grid[r][c] == 8:
                start = r
                while r < h and grid[r][c] == 8:
                    r += 1
                runs.append(r - start)
            else:
                r += 1
    tile = reduce(gcd, runs)

    r0, r1 = min(r for r, c in eight), max(r for r, c in eight)
    c0, c1 = min(c for r, c in eight), max(c for r, c in eight)
    rows, cols = (r1 - r0 + 1) // tile, (c1 - c0 + 1) // tile

    kr0, kr1 = min(r for r, c in clue), max(r for r, c in clue)
    kc0, kc1 = min(c for r, c in clue), max(c for r, c in clue)
    # Rotate the compact colored key clockwise, then enlarge each key cell
    # to the corresponding square tile in the 8-pattern.
    key = [[grid[r][c] for c in range(kc0, kc1 + 1)] for r in range(kr0, kr1 + 1)]
    rotated = [list(row) for row in zip(*key[::-1])]
    if len(rotated) != rows or len(rotated[0]) != cols:
        raise ValueError("rotated key and 8-pattern dimensions do not match")

    for r, c in eight:
        br, bc = (r - r0) // tile, (c - c0) // tile
        color = rotated[br][bc]
        if color:
            out[r][c] = color
    return out
